transform.script:
-- pj-script: luau
return { id="t3", name="t3", output="same",
  create = function(p) return { calculate = function(t, v) return -v end } end }

-- pj-script: luau
return { id="t1", name="t1", output="same",
  create = function(p) return { calculate = function(t, v) return v * 10.0 end } end }

-- pj-script: luau
return { id="t2", name="t2", output="same",
  create = function(p) return { calculate = function(t, v) return -v end } end }
